?>
<div class="lacms-app-wrapper"><?php include __DIR__.'/../layouts/sidebar.php'; ?><main class="lacms-main-content">
<div class="lo-head"><div><div class="lo-eyebrow"><i class="bi bi-stars"></i> Local AI · Decision Support</div><h1>Ollama Planning Assistant</h1><p>Priority scoring, calendar advice, and executive-legislative coordination briefs with a complete local audit trail.</p></div><span class="lo-status <?= $health['available']&&$health['model_installed']?'good':'warn' ?>"><?= e($health['available']&&$health['model_installed']?'AI Ready':'AI Attention Needed') ?></span></div>
<div class="alert <?= $health['available']&&$health['model_installed']?'alert-success':'alert-warning' ?>"><strong><?= e($health['message']) ?></strong><br><small>Model: <?= e(LACMS_OLLAMA_MODEL) ?> · Ollama remains advisory; authorized personnel make final decisions.</small></div>
<div class="row g-3"><div class="col-xl-4"><div class="card lo-card h-100"><div class="card-header"><i class="bi bi-list-stars"></i> Legislative Priority</div><div class="card-body"><p class="small text-muted">Score public impact, readiness, urgency, and strategic alignment.</p><select class="form-select mb-3" id="prioritySelect"><option value="">Select measure...</option><?php foreach($priorities as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $requestedType==='priority'&&$requestedId===(int)$r['id']?'selected':'' ?>><?= e($r['reference_number'].' — '.$r['title']) ?></option><?php endforeach; ?></select><button class="btn btn-primary w-100 ai-run" data-type="priority" data-select="prioritySelect"><i class="bi bi-stars"></i> Analyze Priority</button></div></div></div>
<div class="col-xl-4"><div class="card lo-card h-100"><div class="card-header"><i class="bi bi-calendar-check"></i> Calendar Advisory</div><div class="card-body"><p class="small text-muted">Explain deterministic time overlaps and recommend coordination steps.</p><select class="form-select mb-3" id="calendarSelect"><option value="">Select event...</option><?php foreach($events as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $requestedType==='calendar'&&$requestedId===(int)$r['id']?'selected':'' ?>><?= e($r['event_reference'].' — '.$r['title']) ?></option><?php endforeach; ?></select><button class="btn btn-primary w-100 ai-run" data-type="calendar" data-select="calendarSelect"><i class="bi bi-stars"></i> Analyze Schedule</button></div></div></div>
