</main></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{const out=document.getElementById('aiResult'),status=document.getElementById('aiStatus'),approval=document.getElementById('priorityApproval');let last=null,lastId=0;
 const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
 const render=(value)=>{if(Array.isArray(value)){if(!value.length)return '<span class="text-muted">None</span>';return '<ul>'+value.map(v=>'<li>'+(typeof v==='object'?render(v):esc(v))+'</li>').join('')+'</ul>';}if(value&&typeof value==='object')return '<div class="row g-3">'+Object.entries(value).filter(([k])=>!['success','model'].includes(k)).map(([k,v])=>'<div class="col-md-6"><small class="text-uppercase text-muted">'+esc(k.replaceAll('_',' '))+'</small><div>'+render(v)+'</div></div>').join('')+'</div>';return '<strong>'+esc(value)+'</strong>';};
 document.querySelectorAll('.ai-run').forEach(btn=>btn.onclick=async function(){const sel=document.getElementById(this.dataset.select);if(!sel.value)return Swal.fire('Select Record','Choose a record before running AI.','info');this.disabled=true;const old=this.innerHTML;this.innerHTML='<span class="spinner-border spinner-border-sm"></span> Working...';approval?.classList.add('d-none');try{const fd=new FormData();fd.append('csrf_token','<?= e(csrfToken()) ?>');fd.append('analysis_type',this.dataset.type);fd.append('record_id',sel.value);const r=await fetch('ajax_ai_planning.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:fd}).then(x=>x.json());if(!r.success)throw new Error(r.message||'Analysis failed.');last=r.data;lastId=Number(sel.value);out.innerHTML=render(last);status.textContent=r.message+' · '+(last.model||'Ollama');if(this.dataset.type==='priority')approval?.classList.remove('d-none');}catch(e){Swal.fire('Ollama AI',e.message,'error');}finally{this.disabled=false;this.innerHTML=old;}});
 document.getElementById('btnApplyPriority')?.addEventListener('click',async()=>{if(!last||!last.recommended_priority)return;const ask=await Swal.fire({title:'Apply recommended priority?',text:'You are confirming '+last.recommended_priority+' after reviewing the AI scores and rationale.',showCancelButton:true,icon:'question'});if(!ask.isConfirmed)return;const fd=new FormData();fd.append('csrf_token','<?= e(csrfToken()) ?>');fd.append('analysis_type','apply_priority');fd.append('record_id',lastId);const r=await fetch('ajax_ai_planning.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:fd}).then(x=>x.json());if(r.success){await Swal.fire('Applied',r.message,'success');location.reload();}else Swal.fire('Apply Failed',r.message,'error');});
});
</script>
